def frames(path):
    import cv2
    cap = cv2.VideoCapture(path)
    if not cap.isOpened():
        raise OSError(path)
    fps = cap.get(cv2.CAP_PROP_FPS) or 30.0
    index = 0
    try:
        while True:
            ok, frame = cap.read()
            if not ok:
                break
            pts_ms = cap.get(cv2.CAP_PROP_POS_MSEC)
            timestamp_s = pts_ms / 1000.0 if pts_ms >= 0 else index / fps
            yield frame, {'frame_index': index, 'timestamp_s': timestamp_s, 'width': frame.shape[1], 'height': frame.shape[0]}
            index += 1
    finally:
        cap.release()

def infer(tensor, session):
    raw = session.run(['output0'], {'images': tensor})[0]
    return raw

def process(raw, geometry, frame, conf_thres=None, iou_thres=0.7):
    import numpy as np
    if conf_thres is None:
        conf_thres = 0.25
    labels = ('Helmet', 'LP', 'No helmet')
    predictions = np.asarray(raw, dtype=np.float32)[0].T
    boxes = []
    for row in predictions:
        class_id = int(np.argmax(row[4:7]))
        confidence = float(row[4 + class_id])
        if confidence < conf_thres or class_id not in (0, 2):
            continue
        cx, cy, w, h = map(float, row[:4])
        ratio, px, py = geometry['ratio'], geometry['pad_left'], geometry['pad_top']
        x1 = max(0.0, min(float(frame.shape[1]), (cx - w / 2 - px) / ratio))
        y1 = max(0.0, min(float(frame.shape[0]), (cy - h / 2 - py) / ratio))
        x2 = max(0.0, min(float(frame.shape[1]), (cx + w / 2 - px) / ratio))
        y2 = max(0.0, min(float(frame.shape[0]), (cy + h / 2 - py) / ratio))
        if x2 > x1 and y2 > y1:
            boxes.append({'bbox_xyxy': [x1, y1, x2, y2], 'score': confidence, 'class_id': class_id, 'label': labels[class_id]})
    def iou(a, b):
        ax1, ay1, ax2, ay2 = a
        bx1, by1, bx2, by2 = b
        intersection = max(0.0, min(ax2, bx2) - max(ax1, bx1)) * max(0.0, min(ay2, by2) - max(ay1, by1))
        area_a = (ax2 - ax1) * (ay2 - ay1)
        area_b = (bx2 - bx1) * (by2 - by1)
        return intersection / (area_a + area_b - intersection + 1e-9)
    kept = []
    for box in sorted(boxes, key=lambda item: item['score'], reverse=True):
        if all(box['class_id'] != prior['class_id'] or iou(box['bbox_xyxy'], prior['bbox_xyxy']) <= iou_thres for prior in kept):
            kept.append(box)
    return {'candidates': kept, 'rider_detection_supported': False, 'limitation': 'The selected model detects Helmet and No helmet, not riders; these are head-class candidates only.'}

