class Tracker:
    def __init__(self, association_iou_threshold=0.3, compliance_match_iou_threshold=0.5, max_missed_frames=30):
        self.tracks = {}
        self.next_id = 1
        self.association_iou_threshold = association_iou_threshold
        self.compliance_match_iou_threshold = compliance_match_iou_threshold
        self.max_missed_frames = max_missed_frames

    @staticmethod
    def iou(a, b):
        ax1, ay1, ax2, ay2 = a
        bx1, by1, bx2, by2 = b
        intersection = max(0.0, min(ax2, bx2) - max(ax1, bx1)) * max(0.0, min(ay2, by2) - max(ay1, by1))
        area_a = max(0.0, ax2 - ax1) * max(0.0, ay2 - ay1)
        area_b = max(0.0, bx2 - bx1) * max(0.0, by2 - by1)
        return intersection / (area_a + area_b - intersection + 1e-9)

    def process(self, candidate_record, compliance_record, source_meta):
        candidates = candidate_record['candidates']
        detections = compliance_record['detections']
        pairs = []
        for track_id, track in self.tracks.items():
            for candidate_index, candidate in enumerate(candidates):
                overlap = self.iou(track['bbox_xyxy'], candidate['bbox_xyxy'])
                if overlap >= self.association_iou_threshold:
                    pairs.append((overlap, track_id, candidate_index))
        assigned_tracks, assigned_candidates, assignments = set(), set(), {}
        for overlap, track_id, candidate_index in sorted(pairs, reverse=True):
            if track_id not in assigned_tracks and candidate_index not in assigned_candidates:
                assigned_tracks.add(track_id)
                assigned_candidates.add(candidate_index)
                assignments[candidate_index] = track_id
        for track_id, track in list(self.tracks.items()):
            if track_id not in assigned_tracks:
                track['missed'] += 1
                if track['missed'] > self.max_missed_frames:
                    del self.tracks[track_id]
        for candidate_index, candidate in enumerate(candidates):
            if candidate_index not in assignments:
                track_id = self.next_id
                self.next_id += 1
                self.tracks[track_id] = {'bbox_xyxy': candidate['bbox_xyxy'], 'missed': 0}
                assignments[candidate_index] = track_id
            track = self.tracks[assignments[candidate_index]]
            track['bbox_xyxy'] = candidate['bbox_xyxy']
            track['missed'] = 0
        used_detections = set()
        events = []
        for candidate_index, candidate in enumerate(candidates):
            matches = [(self.iou(candidate['bbox_xyxy'], detection['bbox_xyxy']), j) for j, detection in enumerate(detections) if j not in used_detections]
            overlap, match_index = max(matches, default=(0.0, -1))
            detection = detections[match_index] if overlap >= self.compliance_match_iou_threshold else None
            if detection is not None:
                used_detections.add(match_index)
            status = ('helmet' if detection['label'] == 'Helmet' else 'no helmet') if detection is not None else 'unknown'
            events.append({'rider_id': None, 'candidate_id': assignments[candidate_index], 'rider_verified': False, 'helmet_status': status, 'timestamp_s': source_meta['timestamp_s'], 'frame_index': source_meta['frame_index'], 'bbox_xyxy': candidate['bbox_xyxy'], 'confidence': detection['score'] if detection is not None else None})
        return {'frame_index': source_meta['frame_index'], 'timestamp_s': source_meta['timestamp_s'], 'events': events, 'rider_detection_supported': False, 'limitation': candidate_record['limitation']}

def write_video(frame_results, path, fps=30.0):
    import cv2
    import os
    os.makedirs(os.path.dirname(path), exist_ok=True)
    writer = None
    try:
        for frame, result in frame_results:
            annotated = frame.copy()
            cv2.putText(annotated, 'Rider detection unavailable; IDs are helmet-class candidates', (20, 35), cv2.FONT_HERSHEY_SIMPLEX, 0.7, (0, 165, 255), 2)
            for event in result['events']:
                x1, y1, x2, y2 = map(int, event['bbox_xyxy'])
                color = (0, 0, 255) if event['helmet_status'] == 'no helmet' else (0, 200, 0) if event['helmet_status'] == 'helmet' else (0, 165, 255)
                cv2.rectangle(annotated, (x1, y1), (x2, y2), color, 2)
                cv2.putText(annotated, 'Candidate {}: {}'.format(event['candidate_id'], event['helmet_status']), (x1, max(55, y1 - 8)), cv2.FONT_HERSHEY_SIMPLEX, 0.6, color, 2)
            if writer is None:
                height, width = annotated.shape[:2]
                writer = cv2.VideoWriter(path, cv2.VideoWriter_fourcc(*'mp4v'), fps, (width, height))
                if not writer.isOpened():
                    raise OSError(path)
            writer.write(annotated)
    finally:
        if writer is not None:
            writer.release()
